export const agentsMeta={slug:"post-training/agents",title:"Agent Training and Environments",description:"Construct executable tasks, preserve recovery histories, train through diverse harnesses, and assign grounded outcome and process credit without losing the collection contract.",date:"2026-07-25",updated:"2026-10-18",topicPath:["post-training"],tags:["agentic RL","agents","environments","harnesses","multi-harness","GRS","GAR","recovery masking","token-in token-out","task synthesis"],kind:"dense-topic",prototype:true,visibility:"public",learningGoals:["Build independently verifiable executable tasks","Separate harness diversity, collection bias and training weights","Assign quality credit while preserving correctness and trace lineage"],related:["post-training/rl","post-training/sft","post-training/distillation","training/data","training/frontier-recipes","models/compact-recipes","training/numerics"]};
