const code=x=>"<pre><code>"+x.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;")+"</code></pre>";
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"');
const mimoURL="https://huggingface.co/XiaomiMiMo/MiMo-V2.6-Pro-RL/blob/main/MiMo_V2_6_technical_report.pdf";
const dsURL="https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash/blob/main/DeepSeek_V41_Tech_Report.pdf";
const nanURL="https://huggingface.co/Nanbeige/Nanbeige4.2-3B/blob/main/Nanbeige42_report.pdf";
