export function agentsReader(link){
 const parts=[],scenes=agentsScenes(),add=(id,body)=>parts.push(section(id,agentsSections.find(x=>x[0]===id)[1],body));
 const related=(s,t)=>"<a href='"+link(s)+"'>"+t+"</a>";
 add("task-contract",p("An agent acts on a world through tools. A good-looking final response does not establish that the agent changed that world correctly. Training needs evidence from the resulting state: tests pass, a file is valid, a workflow finishes, or an independent checker confirms the requested change.")+eq(String.raw`\mathcal T=(s_0,g,\mathcal U,B,V)`, "s₀ is the initial environment state; g the goal; 𝒰 the available tools; B the budget; V the verifier. A trajectory records observations, actions and transitions, not only the final answer.")+p("For a repository repair, the initial state includes a broken revision and its dependencies. The goal describes the required behavior. The verifier checks the modified repository. The agent can use several valid patches; training need not prescribe a single reference trajectory.")+p("This makes environment construction part of the learning algorithm. A broken dependency can turn a valid patch into an apparent failure. A leaked answer can turn an invalid policy into an apparent success. Both change the reward distribution before the optimizer receives anything."));
 add("boundaries",table("Five distinct responsibilities",["Component","Responsibility","Failure that belongs here"],[["Task","Required change, initial assets, budget and success criteria","Ambiguous or impossible requirement"],["Policy","Choose actions from the available history","Wrong decision despite valid observations"],["Harness","System prompt, tool schema, context management and stopping","Malformed calls or lost essential history"],["Environment","Execute actions and expose observations","Broken service, missing dependency or nondeterminism"],["Verifier","Check outcomes against independent criteria","False pass, false failure or leaked answer"]])+p("A harness is the agent program around the model. It can change the tools, observation order and context without changing model weights. A sandbox isolates execution; it does not itself define task correctness. Record these boundaries so an infrastructure failure is not mislabeled as a policy error.")+p("For a CSV-script repair, one harness may offer edit_file(path, content), while another requires a shell patch. Separate an incorrect repair from a correct intended edit expressed through an unsupported tool. Better format validity can improve completion without the same gain in programming reasoning.")+p("The policy-gradient machinery belongs to "+related("post-training/rl","Reinforcement Learning")+". Here the focus is the evidence and execution contract that makes those gradients meaningful."));
 add("factory",p("Start with a grounded seed: a real issue, a document bundle, a service specification or an observed capability gap. Construct the initial assets and task goal. Build the verifier alongside them, then validate the verifier independently. Co-generation makes the parts consistent; it can also create correlated mistakes.")+p("Execute several agents against the task. Compare actual outcomes with the stated requirements. Reject unbuildable environments, tasks solved by leaked artifacts, and checkers that accept unintended shortcuts. Repair legitimate failure cases instead of retaining every generated example.")+p("Separate task acceptance from trajectory acceptance. An excellent task may produce bad demonstrations. A successful trajectory may contain an unreliable turn that should not be an imitation target. Feed validated failures back into task generation to expand coverage rather than merely increasing dataset size.")+table("Task-synthesis loop",["Stage","Evidence retained"],[["1. Select or construct the environment","Versioned executable state"],["2. Sample assets and the initial state","Grounded inputs and dependencies"],["3. Synthesize the goal","Explicit requested change and budget"],["4. Build and independently validate the verifier","Success criteria without answer leakage"],["5. Run one or more agents","Actions, observations and resulting state"],["6. Execute the verifier","Outcome and invalid-environment classification"],["7. Filter trajectories and turns","Accepted paths and target masks"],["8. Feed useful failures into generation","Specific capability gaps for the next cycle"]]));
 add("repository-tasks",p("Historical repository changes supply an executable before-and-after relation. Reconstruct the parent commit before the fix, install the dependencies, and expose the issue without the hidden reference patch. Package that state in an isolated environment with reproducible setup instructions.")+p("The hidden patch helps validate the task factory. It is not an agent-visible answer. Remove accidental solution material from Git history, caches, build artifacts and instructions. A task whose tests already pass at the initial revision does not demonstrate the requested repair.")+p("Keep repository identity, revision, dependency versions, setup failures and test commands in provenance. Split evaluation by repository or time where appropriate. Near-duplicate changes from the same project can otherwise make held-out tasks look independent when they are not."));
 add("test-contract",eq(String.raw`\begin{aligned}\mathrm{F2P}&=(\neg b_{\rm target})\land a_{\rm target}\\\mathrm{P2P}&=b_{\rm regression}\land a_{\rm regression}\end{aligned}`, "b and a are Boolean test-pass indicators before and after the patch. F2P requires a repaired failure; P2P requires previously passing regressions to remain passing.")+p("Suppose a task fixes empty-input handling. The empty-input test must fail initially and pass after repair. A normal-input test must pass at both revisions. Checking only the first condition rewards a patch that fixes one case while breaking ordinary behavior.")+p("Passing these tests is evidence under their coverage, not a proof of all intended semantics. Hidden edge cases and an independent inspector can find exception swallowing, hard-coded answers or unrelated rewrites. Preserve the distinction between an invalid task and a valid task with an incorrect solution."));
 add("tool-environments",table("Three tool-world choices",["World","Useful property","Main limitation"],[["Local executable tools","Controlled state, cheap replay and deterministic checking","May omit real service behavior"],["Live service interfaces","Real authentication, latency and failure behavior","Rate limits, changing state, credentials and poor repeatability"],["Model-simulated tools","Cheap scale and flexible long-tail scenarios","Simulator artifacts or implausible success responses"]])+p("A model-simulated observation is not equivalent to executing the action. Validate schemas, state transitions and impossible outputs. Mock a live service when reproducibility matters, but test whether the mock preserves the failure modes relevant to the task.")+p("Store service and tool versions. Timeouts, authentication failures and transient rate limits need an explicit classification. Do not silently score every failed request as a wrong model decision.")+p("Local worlds can become stale; live worlds can change after a task is constructed. Store the capture time as well as the version. Choose the mixture for the behavior that must transfer, not simply the easiest world to scale."));
 add("tool-composition",p("Model Context Protocol (MCP) specifications and API descriptions can provide tool schemas. Useful tasks require meaningful dependencies among tools. Searching for a customer, reading that customer's orders and updating the selected order is a workflow; listing hundreds of unrelated endpoints is not.")+p("Construct tasks that require earlier outputs as later arguments. Validate entity identity, parameter constraints and state consistency across calls. Include recoverable errors, pagination and ambiguous matches when those behaviors are grounded in the interface.")+p("Nanbeige4.2 describes thousands of MCP specifications, implemented through local Python, live MCP services and model-simulated components. That count describes available specifications, not independently validated tasks or universal tool competence."));
 add("artifacts",p("Office tasks begin with actual document, spreadsheet, slide or PDF assets. A request can combine them: read a source sheet, compute a summary and place it in a presentation. The deliverable is the file bundle, not an explanation of what the agent intended to produce.")+p("Check structure and content separately. A spreadsheet formula can exist but have stale displayed values. A slide deck can contain the right words but clip its labels. Recalculate numerical outputs, inspect rendering and verify agreement across files.")+p("Keep input assets and expected invariants together. A generated artifact may serve as a later input only after independent validation. Provenance should identify the source bundle, transformation and checks that established acceptance.")+p("For synthesis, collect artifacts across domains, cluster by topic and structure, and sample coherent bundles. Let the task generator inspect the bundle before writing the goal and rubric. Then run the agent in isolation and judge both the delivered files and the useful trajectory. Input-file diversity and executable checks serve different purposes."));
 add("visual-loop",p("Visual agent work introduces another observation channel. The agent writes or edits, renders or runs the result, inspects what appears, receives a judgment and revises. A successful source-code edit can still produce an unusable visible interface.")+table("Visual feedback loop",["Step","Evidence"],[["Write or edit","Requested source change"],["Render or run","Actual executable result"],["Inspect","Screenshot, layout and interaction state"],["Judge","Task-specific visual and functional criteria"],["Revise","New action conditioned on observed defects"]])+p("GLM-5.3 describes frontend RL around real user flows, layout, interaction and GUI-based feedback. The report scope does not disclose enough to infer environment counts, exact reward formulas or verifier accuracy. Visual quality claims need the evaluation harness and judge conditions, not only the checkpoint name."));
 add("recycling",p("Validated outputs can enlarge the initial-asset pool. A completed report becomes an input for a consistency task; a repaired workbook becomes a base for a new analysis. This expands workflows without generating every asset from nothing.")+p("Recycling also propagates hidden defects. Independent checks, provenance and human-source anchoring limit that drift. Deduplicate related descendants and prevent an output or its hidden solution from entering both training and evaluation.")+p("Judge diversity as well as volume. Repeated synthetic formatting and assumptions can teach a narrow agent style. Real documents, grounded specifications and adversarial failure cases help reveal that narrowing."));
 add("knowledge-graph",p("Kimi K3 describes hierarchical task construction through a knowledge graph. Retrieve grounded material from a seed, expand it into atomic requirements, reuse validated nodes, and combine dependencies into larger tasks. A directed acyclic graph makes prerequisite relationships explicit.")+p("The graph should encode actual dependence, not topic proximity. If step B needs the result of A, record that edge. If A and B merely discuss related subjects, forcing an order invents a prerequisite. Preserve source links and deduplicate reused nodes.")+p("Combined tasks need fresh end-to-end validation. Correct atomic nodes do not guarantee a valid composite: their file versions, assumptions or tool states may conflict. Task difficulty can grow through dependencies while final verification remains independent.")+p("Expansion stops at sufficiently atomic concepts. Reuse grounded nodes, then sample linked concepts across levels. A composite can require general and specialized knowledge, text and vision, or several dependent tools. This is inspectable coverage, not a guarantee that the generated prerequisite graph is correct."));
 add("autonomous-tasks",p("K3's Autonomous Execution Tasks specify a goal, an initial environment, available operations, budgets and independent verification. They need not provide a reference execution path. Several action sequences can reach a correct final state.")+p("Separate public diagnostics from hidden final checking. Public feedback can explain an invalid file or missing field. Hidden criteria evaluate completion without becoming an unrestricted answer oracle. Limit submissions and record diagnostic exposure.")+p("Budgets are part of the task definition. An unlimited agent with unlimited checker access solves a different problem from a bounded agent. Avoid rewarding repeated hidden-check probing as ordinary progress."));
 add("curriculum",p("Mine failures from seed agents and classify the missing capability. Useful axes include horizon, tool depth, parameter complexity, ambiguity, cross-artifact consistency, recovery and verification. Length alone is not a complete difficulty measure.")+p("Increase difficulty where the policy has enough competence to produce useful contrast. A task that nearly every attempt fails can produce little outcome differentiation. A task that every attempt passes can still teach quality through a suitable grading signal.")+p("Compact agents may benefit from shorter solvable tasks rather than the hardest available environments. Nanbeige4.2 uses relatively high pass@8 and short trajectories in its agent RL selection. Keep those conditions attached to that recipe; they do not define a universal curriculum.")+p("Do not discard every recovery trace to make the data look clean. Perfect-only demonstrations remove examples of responding to realistic tool errors."));
 add("recovery",p("A successful trace can include an unsupported tool call followed by a valid correction. Retain the unsupported action and its error observation in the input history. Mask the bad assistant action from supervised targets, then train the corrected action under that real history.")+scenes.recovery+p("The distinction is between conditioning tokens and target tokens. Prompt and tool-observation tokens can affect the next prediction without receiving assistant imitation loss. Deleting the mistake changes the conditional problem and may hide the recovery skill.")+p("GLM-5 retains recoverable unsuccessful turns in long-context SFT data with selective masking. Nanbeige4.2 filters malformed, looping, redundant or truncated action targets while keeping useful context. Decide which turns are unreliable; do not mark the entire successful trajectory correct by default.")+eq(String.raw`\mathcal L=\sum_t m_t\ell_t,\qquad m_t\in\{0,1\}`, "mₜ selects reliable assistant targets; ℓₜ is their declared supervised loss. Masked tokens can remain in the conditioning history. A mean needs an explicit positive target-count denominator."));
 add("harnesses",p("The same model can behave differently in different agent programs. Tool names, system instructions, context folding, memory, skills and subagents alter what the model observes and how an action is interpreted. Multi-harness training varies these interfaces while sharing policy weights.")+eq(String.raw`J(\theta)=\mathbb E_{\substack{(\mathcal T,h)\sim\mu\\\zeta\sim P_{\theta}(\cdot\mid\mathcal T,h)}}[R(\mathcal T,h,\zeta)]`, "μ is the chosen task/harness distribution; ζ is an executed trajectory; Pθ includes policy actions and environment transitions. This conceptual objective is not an optimizer specification. Changing μ changes the objective.")+p("K3 uses configurable white-box modules for tools, system prompts, context, skills, memory and subagents. Controlled variation helps identify whether a failure comes from task reasoning or interface adaptation. Version the modules; a silent prompt or tool edit changes the training distribution.")+p("Different scaffolds can expose broad exploration, localized search, direct editing, test-first debugging and different recovery paths. The desired transfer is task competence across interfaces. A stronger average over the training harnesses does not guarantee competence on each harness or an unseen one."));
 add("transfer",table("Two independent generalization axes",["Evaluation tasks","Seen harness","Held-out harness"],[["Seen task families","Familiar operating setting","Interface transfer"],["Held-out task families","Task transfer","Joint task and interface transfer"]])+p("An unseen task is not automatically an unseen harness. A model trained with all evaluation interfaces can improve on held-out tasks without demonstrating transfer to a new agent program.")+p("Hold the task pool, budgets and verifier fixed when comparing harnesses. Record prompt templates, tools, context policy and stopping rules. Otherwise a score difference may reflect more opportunity rather than better interface robustness."));
 add("capture",p("A training proxy can intercept model requests from an unmodified agent program. It translates API dialects, sends the effective prompt to an inference engine, and records the engine's exact prompt IDs, generated IDs and behavior log probabilities. The capture boundary must include the prompt the engine actually used.")+p("Decoding generated IDs and re-encoding the text need not recover the sampled sequence. Tool-call reformatting can change both tokenization and the conditioned history. Token-in/token-out (TiTo) training preserves the action sequence instead of reconstructing a plausible transcript.")+p("Prompt tokens and tool observations do not become policy targets merely because they are in a captured call. Declare completion masks and retained branches. An endpoint lacking the required token evidence can support evaluation without supplying a valid training capture.")+p(cite("https://huggingface.co/docs/openenv/environments/harbor","OpenEnv's Harbor capture documentation")+" describes this boundary.")+table("Proxy integration boundary",["Flow","Evidence"],[["Task + harness + sandbox → interaction loop","The runner stays responsible for tool execution and context"],["Model request → capture proxy → inference engine","Exact effective input IDs and sampling settings"],["Engine response → proxy → harness","Exact sampled output IDs and behavior probabilities"],["Token trace → learner; final state → verifier → learner","Policy evidence and independent outcome are joined by task/trajectory identity"]]));
 add("policy-contract",eq(String.raw`\rho_t=\frac{\pi_{\rm current}(a_t\mid H_t)}{\pi_{\rm behavior}(a_t\mid H_t)}`, "Hₜ is the exact recorded conditioning history. The denominator must be positive and must describe the actual sampling policy, including sampling transformations—not today’s model recomputed under the same name.")+p("Temperature, top-k and top-p processing can change the distribution that sampled the action. Record the processed sampling probabilities and support. Raw-logit probabilities are not interchangeable with probabilities after those transformations.")+p("Asynchronous collection adds policy versions. A long episode may cross a synchronization boundary or resume under newer weights. Track the version associated with each segment. Replay and importance corrections cannot recover evidence that was never stored.")+p("See "+related("post-training/rl","RL's sampling and stale-policy contracts")+" for estimator details. An environment transcript alone is insufficient to reconstruct a trustworthy policy update."));
 add("capture-graph",p("Agent programs can branch, retry or compact context. Captured calls therefore form a graph, not necessarily one uninterrupted conversation. Exact prefix matches can link calls; a rewritten context can begin a new root.")+scenes.capture+p("The graph records what was conditioned on and which completions remain in a selected learning path. It does not automatically decide reward propagation. An abandoned branch needs an explicit credit rule rather than inheriting the final answer's success by convenience.")+p("Keep the original IDs even when presenting a shorter readable transcript. Context compaction may preserve semantic information while replacing the exact policy-conditioning state."));
 add("groups",p("Group-relative training compares several attempts under a declared common opportunity. FineEnvs' example uses the same task and harness within each group, with diversity between groups. Mixing arbitrary tasks inside one mean changes the comparison.")+p("Store task, harness, seed, budget and group identity. A slow incomplete group requires an explicit policy: wait, pad under defined conditions, or discard. Do not silently substitute an unrelated completed response to fill the group.")+p("Harness variation within a group is possible as a different design, but unequal interfaces can confound quality and opportunity. Establish comparable action budgets and observations before interpreting relative rewards."));
 add("mixture",p("Equal episode counts do not imply equal token counts, training rows or loss contribution. A long harness can produce more completion targets per episode. The chosen loss reduction decides whether those extra tokens change its total scalar coefficient mass.")+scenes.mixture+eq(String.raw`\begin{aligned}\mathcal L_{\rm response}&=\frac1N\sum_{i=1}^{N}\frac1{T_i}\sum_{t\in\mathcal M_i}\ell_{it}\\\mathcal L_{\rm token}&=\frac{\sum_{i=1}^{N}\sum_{t\in\mathcal M_i}\ell_{it}}{\sum_{i=1}^{N}T_i}\end{aligned}`, "N≥1 is the accepted response count. 𝓜ᵢ contains its unmasked assistant targets and Tᵢ=|𝓜ᵢ|>0. Exclude empty responses under an explicit policy; context length is not this denominator.")+p("Even equal coefficient mass does not establish equal gradient influence. Advantages, clipping, masks and gradient directions can differ. Log the unit you balance and several resulting distributions instead of calling the mixture equal without qualification."));
 add("weighted-mixture",p("Harness weighting is a coherent experimental extension. Group related interfaces into families, select a family, then select a harness within it. This separates coverage across interaction styles from redundancy among nearly identical wrappers.")+eq(String.raw`P(h)=P(F=f(h))\,P(h\mid F=f(h))`, "f assigns each harness to one family. Family probabilities and each within-family distribution separately sum to one. Coding weight .6 split equally between two harnesses gives .3 each; a sole search harness with weight .4 gets .4.")+p("Choose whether the weight applies to task selection, completed episodes, target tokens or the objective coefficient. Applying weights at both sampling and loss stages changes the effective mixture again. Availability and latency can prevent the requested sampling weights from matching accepted training shares.")+p("Potential experiments include uniform families, capability-gap weights, novelty weighting and bounded adaptive allocation. Keep a minimum exposure floor and evaluate held-out interfaces. These are proposed adaptations, not verified FineEnvs results or a demonstrated best weighting rule."));
 add("completion-bias",p("An asynchronous learner consumes completed work. With equal worker counts, a faster harness completes more episodes before an update. The accepted mixture can therefore differ from the dispatched mixture even when task selection is balanced.")+scenes.completion+eq(String.raw`\gamma_h=\frac{c_h}{d_h}`, "cₕ is the number of continuously occupied workers and dₕ>0 their fixed episode duration. γₕ is the constructed long-run completion rate, not a measured system throughput. Variable durations require renewal assumptions; queues, retries and idle time change the rate.")+p("Use completion quotas, deficit-aware scheduling or adaptive concurrency when a target mixture matters. Track dispatched, completed, filtered and accepted shares separately. Token budgets add another axis: equal completed episodes may still give unequal generated-token exposure.")+p("Latency bias and policy staleness are distinct. A balanced set of slow episodes can still be too old. A fresh set of fast episodes can still omit important task families."));
add("efficiency",p("A fast wrong answer should not receive a tool-efficiency reward. Gate any bounded bonus by task correctness.")+eq(String.raw`R(\zeta)=C(\zeta)\left[1+\beta e(\zeta)\right]`, "C is binary correctness, 0 ≤ e ≤ 1 is declared efficiency, and β ≥ 0 controls a bounded bonus. Failure has reward zero. This conceptual construction is not the exact FineEnvs bonus.")+p("This is a teaching formula, not the exact FineEnvs implementation. Define efficiency relative to the task, budget and tool costs. Fewer calls can mean better planning, but also skipped verification or poorer exploration.")+p("Compare cost at matched success rates and inspect common successful tasks separately. A mean tool-call count over all episodes can fall simply because the policy gives up earlier."));
 add("multi-harness-evidence",p("FineEnvs' historical example trains LFM2.5-2.6B with asynchronous GRPO across OpenCode, Claude Code, Codex and Mini-SWE-Agent. Groups contain eight attempts under one task and harness. At step 1,000, mean pass@1 moves from 42.2% to 54.2%; OpenCode-only training reaches 52.3%.")+p("The 1.9 percentage-point difference between training regimes is reported as within noise. The experiments use one seed, unequal data exposure and different compute. All four evaluation harnesses are included during multi-harness training. This comparison supports improvement over the base, not held-out-interface transfer or a universal mixture ranking.")+p("Tool calls fall by about 31% on tasks that both the base and multi-harness models solve. That common-success condition matters. No LFM ablation isolates the efficiency bonus. The result does not show that fewer calls cause higher correctness.")+p(cite("https://huggingface.co/spaces/FineEnvs/multi-harness-rl","FineEnvs multi-harness guide")+" · "+cite("https://fineenvs-multi-harness-rl.hf.space/#training-small-models-across-harnesses","Experiment section")+" supplies the experiment. Its preserved comparison does not establish equal per-task completion counts or a harness-ranking weight scheme."));
 add("binary-saturation",p("Binary correctness is necessary but coarse. For rewards [1,1,1,1], centered group advantages are all zero. The solutions may still differ in edge-case coverage, unwanted side effects, maintainability and unnecessary work.")+eq(String.raw`A_i=R_i-\frac1G\sum_{j=1}^{G}R_j,\qquad R_1=\cdots=R_G\Longrightarrow A_i=0`, "G≥1 is the group size. A positive stabilizer can keep variance-normalized advantages defined; it cannot create contrast between identical rewards.")+p("MiMo's Groupwise Reward Synthesis (GRS) creates quality-sensitive rewards under a correctness gate. Groupwise Advantage Redistribution (GAR) reallocates existing positive binary advantage. These solve related but different problems: GAR cannot create missing binary credit in an all-pass group."));
 add("grs",p("GRS spends grader effort offline. Several varied attempts expose task-specific failure modes and quality differences. A synthesis model builds solution rubrics and behavior rubrics from the task specification, environment evidence and those attempts.")+p("Online scoring applies the rubric to each new solution and process. Solution criteria concern the delivered change; behavior criteria concern evidence gathering, checking and unnecessary actions. Multiply their scores by executable correctness so a failed task remains zero.")+eq(String.raw`R_i=C_iS_iB_i`, "Cᵢ∈{0,1} is executable task completion; Sᵢ and Bᵢ are solution/behavior rubric scores on declared bounded scales. Calibration requires validation. A failed task has zero reward irrespective of rubric scores.")+p("For four passing attempts with combined quality [1,.8,.4,.2], the mean reward is .6 and centered advantages are [.4,.2,−.2,−.4]. Quality creates contrast despite identical binary outcomes. Attempts guide criteria; they do not become ground truth. Reject incidental style rules and criteria contradicted by the specification."));
add("gar",p("GAR instead inspects the current group online. The grader compares patches, test evidence and traces. It scores passing solution quality using suitability, precision, minimality, side effects and craftsmanship. Allow ties when evidence does not justify an ordering.")+p("A confirmed exploit first changes the effective task reward to zero. Recompute the whole group's mean and advantages after that correction. Subtracting weight only from the hacked response would leave every other response's baseline inconsistent.")+eq(String.raw`\lambda=\frac{\sum_{i\in\mathcal P}A_i}{\sum_{i\in\mathcal P}f_iA_i},\qquad A_i^{\prime}=\begin{cases}\lambda f_iA_i&i\in\mathcal P\\A_i&i\notin\mathcal P\end{cases}`, "𝓟 is the passing set in a mixed binary group, with positive Aᵢ and quality fᵢ∈(0,1]. The denominator is positive. This is uncapped redistribution before re-centering; uniform groups need a separate zero-contrast branch.")+p("For [1,1,0,0], binary advantages are [.5,.5,−.5,−.5]. Passing quality [.2,1] gives uncapped "+inlineMath(String.raw`\lambda=\frac53`)+ " and redistributed advantages "+inlineMath(String.raw`\left[\frac16,\frac56,-0.5,-0.5\right]`)+ ". The positive budget remains one, but more credit reaches the better passing solution.")+p("Naive downweighting reduces positive mass while leaving negative mass unchanged. That alters the reinforcement balance. Excessive entropy growth is a possible failure mechanism described by the authors, not a theorem about every optimizer or batch."));
 add("gar-conservation",p("Uncapped normalization preserves total positive mass by construction. A λ cap prevents extreme amplification but can break that equality. Subtracting the new group mean restores zero sum; it does not generally restore the original positive budget.")+scenes.grading+p("In the previous group, a cap of one gives [.1,.5,−.5,−.5] before centering. Subtracting the mean −.1 yields [.2,.6,−.4,−.4]. Passing mass is now .8 rather than one. Treat capped conservation as approximate or conditional, not exact.")+p("All-pass and all-fail binary groups have no positive mass to redistribute. Avoid a zero denominator or invented ranking in that case. GRS can supply new quality contrast; GAR needs existing outcome contrast. Report-specific cap constants must come from the implementation, not this toy."));
 add("local-credit",p("Sequence outcomes can hide localized process defects. For a positive trajectory, mask flagged bad-action targets and redistribute the declared positive credit across clean tokens. Retain the observations needed to understand recovery.")+p("For a negative trajectory, amplify flagged likely-fault tokens by κ&gt;1, then normalize the weights to the declared negative budget. A plausible local cause is still a grading judgment, not a causal proof.")+eq(String.raw`w_t=A\frac{u_t}{\sum_j u_j},\qquad \sum_t w_t=A`, "A is the signed response credit. uₜ≥0 is a recipient score and Σuⱼ>0 is required. Positive credit uses zero scores on flagged targets; negative credit uses κ>1 on flagged targets and 1 elsewhere. This declared teaching normalization is not every production loss reduction.")+p("With positive mass one and flags [true,false,false,false], clean tokens receive "+inlineMath(String.raw`\frac13`)+ " each and the flagged token zero. With negative mass −1 and "+inlineMath(String.raw`\kappa=2`)+ ", scores [2,1,1,1] give weights [−.4,−.2,−.2,−.2]. If every token is flagged, positive redistribution has no clean recipient: drop or report unallocated mass. Uniform negative amplification cancels after normalization.")+p("Outcome and process rewards are another independent choice. Outcome asks whether the task finished. Process scores can concern tool validity, correct parameters, information gain, state progress, repetition and recovery. A generic additive form is below; it is not MiMo’s GRS or GAR formula.")+eq(String.raw`R(\zeta)=R_{\rm outcome}(\zeta)+\eta\sum_tR_{\rm process}(a_t,s_t)`, "ζ is an executed trajectory; η≥0 scales the declared process score. This conceptual additive construction has no automatic correctness veto. Bound or gate shaping so plausible local actions cannot outweigh required completion."));
 add("length",p("Length regularization should follow sufficient competence. Penalizing long attempts on a task the policy cannot solve can suppress exploration rather than remove waste. MiMo conditions length control on a group pass-rate threshold.")+p("Among successful trajectories, a chosen length percentile sets the reference. A tolerance permits necessary variation. Only excess length receives a smoothly increasing capped penalty. The threshold, percentile, tolerance and cap are recipe parameters, not universal constants.")+p("Separate explicit length penalties from loss reduction. Taking a token mean within each response controls its coefficient mass; it does not directly penalize generating more tokens. Compare accuracy, recovery and verification frequency alongside length."));
 add("grader-lifecycle",p("An asynchronous grader can store heavy trajectory payloads separately from lightweight control metadata. The collector submits a trace; grading later returns outcomes, rubric scores or corrected exploits. That overlap reduces waiting without making provisional scores final.")+p("Finalize rewards, masks and group membership before computing accepted advantages. A late confirmed hack changes the whole group's statistics. Do not allow a race where a provisional reward trains the policy and the correction arrives afterward.")+p("Define a failure policy for grader timeouts or invalid outputs. A report can fall back to the original executable reward rather than inventing a score. Record which reward path was used and compare fallback rates by source. Expensive grading is useful only if its criteria and latency improve accepted signal."));
 add("lifecycle",table("Rollout hierarchy",["Unit","Contains","Why it matters"],[["Sample","One task instance and its candidate sequences","Shared task, budgets and grading identity"],["Sequence","One attempted solution, potentially with branches","Outcome and chosen learning path"],["Context","One exact conditioning history, including compaction","Token identity and cache ownership"],["Segment","A generation span under declared policy state","Behavior probabilities and interruption lineage"]])+p("A context rewrite and a resumed segment are different events. The first changes conditioning tokens. The second may continue the same context under another policy version. Track both instead of flattening all records into one text transcript.")+p("Keep large logs, screenshots and artifacts in payload storage. Driver memory should hold control references rather than every complete rollout. Preserve immutable identifiers so resumed work and graders refer to the same evidence."));
 add("interruption",p("Long episodes can hold resources while waiting for tools. Keep environment state outside a preemptible GPU pool. Suspend generation at a safe token boundary, preserve cache and route state where supported, and resume with explicit segment lineage.")+p("K3 partial rollouts pause unfinished work once a fraction completes and continue it in a later iteration. The available description does not disclose a universal fraction. Newer-policy resumption introduces staleness; it is not one ordinary uninterrupted on-policy sample.")+p("DeepSeek describes time-shared GPU phases with persisted key-value state, expert routes and recorded policy versions. Route replay supports numerical consistency; it does not erase the behavioral change introduced by different weights. Reconstruct the trajectory according to its actual segments."));
 add("integrity",p("The verifier is part of the attack surface. An agent can optimize reward by reading leaked patches, modifying tests, exploiting exception handling or manipulating grader-visible files. A passing test command is not enough when the command or its environment can be attacked.")+p("Clean build logs, patch caches, bytecode, post-base Git references and answer-bearing artifacts. Restrict network access according to the task. Use independent inspectors, adversarial probe agents and fresh audits on new trajectories.")+p("A sandbox crash or infrastructure fault needs an explicit failure signal. Distinguish invalid execution from a valid wrong action. MiMo reports confirmed hacking below 2% in its final run under its detection process; that is not an upper bound on undetected exploits.")+p("Keep evaluation infrastructure separate and hardened. Do not train toward known checker loopholes while treating the resulting score as task competence."));
 add("glm",p("GLM-5 combines long-context SFT recovery data with asynchronous agentic RL. Its maximum SFT context is 202,752 tokens. More than 1,000 simultaneous rollouts use a TiTo gateway, direct double-sided importance sampling and filtering for stale or invalid runs.")+p("Incomplete groups can be padded when enough valid attempts remain, or dropped. Periodic weight synchronization and optimizer resets affect the training state. Rollout-ID consistent hashing preserves cache locality; FP8, multi-token prediction and prefill/decode separation serve execution efficiency, not task verification.")+p("Environment construction spans more than 10,000 software tasks from roughly a thousand repositories in nine languages: Python, Java, Go, C, C++, JavaScript, TypeScript, PHP and Ruby. Thousands of Docker/Harbor terminal tasks report build success above 90%. A search knowledge graph covers over two million pages. Slide tasks combine static, runtime and perceptual checks.")+p("Context management changes measured behavior. Folding old tool observations while retaining five recent rounds moves BrowseComp from 55.3 to 62.0. A 32K discard rule gives 75.9 in the stated setup. These are harness/context results, not isolated architectural effects. "+cite("https://arxiv.org/abs/2602.15763","GLM-5 report")+" provides the recipe."));
 add("nanbeige",p("Nanbeige4.2 constructs repository tasks with hidden patches and both F2P and P2P tests. Claude Code, OpenHands, SWE-agent and Codex generate scaffold-diverse traces. Its tool worlds mix local, live and simulated components; validated office artifacts support recycling.")+table("Nanbeige4.2 supervised target-token mixture",["Context stage","Reasoning","General","Agentic"],[["64K","82.7%","11.6%","5.7%"],["128K","47.8%","22.7%","29.5%"],["256K","22.4%","8.7%","68.9%"]])+p("These are target-token shares, not task counts. Longer context stages allocate more supervised exposure to agentic content. The table does not isolate the causal contribution of context length from data mixture.")+p("For the compact 3B model, agent RL favors relatively high pass@8 and shorter trajectories. The report summary records an approximately 20% reduction in normalized single-turn error; do not read that as 20 percentage points without the original metric units. Validation rises from 66.0 to a peak of 71.0, not necessarily the final checkpoint score.")+p(cite(nanURL,"Nanbeige4.2 report")+" gives the context. "+related("models/compact-recipes","Compact Model Recipes")+" owns its architecture and broader schedule."));
 add("mimo",p("MiMo-V2.6's task mixture is 68% coding, 12% general tool use, 13% visual/aesthetic work, 3% context tasks and 4% cybersecurity. Coding includes real issues, pull requests, repository/specification workflows and expanded horizons. Tools include deterministic files, mocked APIs, CLI, GUI and MCP workflows.")+p("Cybersecurity tasks use verifiable environments such as OSS-Fuzz with sanitizer evidence. They belong to grounded execution and grading here, not a recreated inventory of individual challenge write-ups.")+p("MiMo samples groups of 16. Frequent all-pass groups motivate GRS; quality differences in mixed groups motivate GAR. Ablation conditions include changing turn and token distributions, so the comparison does not establish a perfectly compute-matched isolated component effect.")+p("Training through four coding interfaces raises the reported held-out-harness mean from roughly 50% to 66%. Unlike the FineEnvs all-seen-interface comparison, this addresses interface transfer under the report's stated task/evaluation conditions. "+cite(mimoURL,"MiMo report")+" contains the methods and results."));
 add("deepseek-factory",p("DeepSeek-V4.1-Flash uses voluntarily returned hard or failed sessions, deduplicated, and selected repositories as task seeds. Repository-star thresholds and some selection settings are not disclosed. A planner specifies the target behavior, buildability, regressions and external-resource needs.")+p("A builder installs dependencies and constructs the initial working tree, instructions and tests. It validates its setup, then removes leaked reference material before packaging the container layer. Several solvers attempt the task. An independent inspector checks consistency, unintended solutions and exploitability.")+p("Repair addresses invalid tasks and adjusts difficulty. Task constructors are themselves trained with difficulty and correctness signals. Fresh solver trajectories re-audit tasks when they enter later RL runs; construction is ongoing maintenance rather than one initial dataset export.")+p("General workflows include mocked SaaS and enterprise backends built from observed API behavior, schemas and constraints. Failure feedback improves them. Mocked fidelity remains a validation question, not a consequence of successful execution. "+cite(dsURL,"DeepSeek report, §5.1")+" is the source."));
 add("deepseek-systems",p("DeepSeek's DSec infrastructure supports demand for millions of concurrent sandbox instances. That is not a count of unique validated tasks or dedicated cores. For comparable workloads, live-container density increases from about 1,000 to over 2,500 per node, not 2,500 simultaneous repository builds.")+p("Scale units and relaxed scheduler replicas reduce coordination cost; final node admission still protects resource limits. Sub-NUMA binding improves locality. Background work uses SCHED_IDLE and priority isolation, with hyperthread-aware placement where described. AppArmor and eBPF enforce per-sandbox restrictions.")+p("Crashes produce explicit failure information. Preserve the task's environment while GPU generation is preempted. Versioned Claude Code, OpenCode, Pi and DeepSeek scaffolds expand interface conditions. Sample-level dispatch need not wait for previous group stragglers; it does not justify mixing unrelated prompts inside advantage groups.")+p("Completion quotas, optional early rejection of short work, waiting bounds and masks for too-old tokens regulate collection. The report does not disclose universal numerical thresholds for these controls. Throughput gains require both mixture and staleness management."));
 add("collection-systems",p("MiMo's 25 sources vary by roughly 90× in generated tokens and 66× in rollout duration. Fixed concurrency alone cannot maintain a target mixture. Adaptive concurrency, deficit-aware scheduling, predictive cache dispatch and bounded replay manage that heterogeneity.")+p("Numerical execution also matters. MiMo uses MXFP4 alignment with quantize-dequantize after updates, expert-route replay and top-p candidate replay. These address specific rollout/training mismatches; using the same checkpoint identifier alone does not establish the same sampled distribution.")+p("Predictive memory estimates can become stale. Restart paths and cache-memory pools need explicit accounting. Hardware or network failures should not be attributed to policy decisions without evidence. Link numerical details to "+related("training/numerics","Precision and Quantization")+", routing to "+related("models/moe","Mixture of Experts")+" and update semantics to "+related("post-training/rl","RL")+"."));
 add("implementation",p("First implement task acceptance independently of the solver. This conceptual kernel requires both test families and distinguishes invalid initial states from failed repairs. The production checker must also protect its own files and execution path.")+code("def valid_repair(before, after):\n    target_was_broken = not before.target_pass\n    target_is_fixed = after.target_pass\n    regression_was_valid = before.regression_pass\n    regression_is_safe = after.regression_pass\n    return (target_was_broken and target_is_fixed\n            and regression_was_valid and regression_is_safe)")+p("Next preserve aligned captured arrays [T] for generated IDs, behavior log probabilities and masks. An entire context has separate prompt/observation IDs. The example assumes every returned log probability corresponds to the processed distribution that generated that ID.")+code("capture = engine.generate(effective_prompt_ids, sampling)\nassert len(capture.ids) == len(capture.behavior_logp)\nrecord = {\n    'prompt_ids': effective_prompt_ids,\n    'completion_ids': capture.ids,\n    'behavior_logp': capture.behavior_logp,\n    'policy_version': capture.version,\n    'sampling': sampling,\n    'target_mask': retained_assistant_mask,\n}\nvalidate_and_store(record)")+p("Validation checks finite probabilities, masks, lineage, support and task identity before training acceptance. Neither kernel is a complete training loop. Keep reward finalization and group statistics outside the environment's action handler."));
 add("evaluation",table("Read the failure before tuning the policy",["Observation","Check"],[["Good text, wrong artifact","Final-state verifier and rendered outputs"],["High pass rate, fragile patches","Hidden semantics, exploit checks and quality rubrics"],["New harness fails familiar tasks","Tool schema, system prompt and context contract"],["Long traces dominate training","Target lengths and loss reduction"],["Fast source dominates updates","Completed/accepted mixture and scheduling"],["Unexpected update mismatch","Exact IDs, sampling processing, version and routes"],["Recovery weak despite clean SFT","Whether realistic errors survived as conditioning context"],["Grader gains with worse correctness","Rubric calibration, veto gate and reward races"]])+p("Report task success and confidence intervals by task family and harness. Include held-out interfaces when claiming interface transfer. Evaluate cost, latency, calls, target length, recovery and invalid-environment rates under matched budgets.")+p("A useful ablation changes one contract at a time: task pool, harness mixture, rubric, length rule or scheduler. Record compute and accepted exposure. Keep independent inspectors and selected human review for failures that automated metrics miss."));
 add("history",p("Agent training extends demonstrated tool use into executable, outcome-grounded tasks. Repository history supplies initial states and regression tests. Synthetic factories expand tool and artifact workflows. Recovery masking teaches correction without copying every failed action.")+p("As policies and workloads grow, interface transfer and heterogeneous collection become separate problems. TiTo capture preserves the sampled evidence. Multi-harness training varies the agent program; scheduling controls which completed work reaches the learner.")+p("Binary success then saturates on solvable tasks. GRS supplies task-specific quality contrast; GAR redirects existing mixed-group credit. Long-horizon interruption, adversarial inspection and environment isolation keep the resulting evidence valid. These are connected engineering branches, not one sequence in which each new report replaces every earlier method."));
add("sources",p(cite(kimiURL,"Kimi K3 report")+" · "+cite(nanURL,"Nanbeige4.2 report")+" · "+cite(mimoURL,"MiMo-V2.6 report")+" · "+cite(dsURL,"DeepSeek-V4.1 report")+" · "+cite("https://arxiv.org/abs/2602.15763","GLM-5 report"))+p(cite("https://huggingface.co/spaces/FineEnvs/multi-harness-rl","FineEnvs multi-harness guide")+" · "+cite("https://huggingface.co/docs/openenv/environments/harbor","OpenEnv Harbor")+" · "+cite("https://huggingface.co/blog/huggingface/tito","Token-In, Token-Out")+" · "+cite("https://huggingface.co/docs/trl/async_grpo_trainer","TRL asynchronous GRPO"))+p(related("post-training/rl","Reinforcement Learning")+" · "+related("post-training/sft","SFT and Adaptation")+" · "+related("post-training/distillation","Distillation")+" · "+related("training/data","Training Data")+" · "+related("training/frontier-recipes","Frontier Recipes"))+p("The visual models use invented token IDs, lengths, durations and quality values. Their outputs follow exact declared calculations. They are explanations, not measured training results or replicas of a full production scheduler."));
 return topic(agentsMeta,agentsSections,"Executable evidence, diverse interfaces and precise credit: how an agent's interaction with a world becomes usable training data.",parts.join("\n"));
}
export function mountAgents(scope=document){mountTopic(scope,agentsMeta.slug,article=>mountAgentsScenes(article));}
